UPDATE `quest_template_locale` SET `Details` = 'Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.', `VerifiedBuild` = 0 WHERE `locale` = 'esES' AND `ID` = 5094;
