UPDATE `quest_template_locale` SET `Details` = 'Lleva la nota desgastada al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.', `VerifiedBuild` = 0 WHERE `locale` = 'esES' AND `ID` = 9299;
